import csv, re
from datetime import date
from collections import defaultdict

RUN_DATE = date(2026,6,30)

def load_csv(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))

def norm(s):
    return s.strip().lower() if s else s.strip()

def parse_amount(s):
    s = s.strip().replace('$','').replace(',','').strip()
    return float(s)

def parse_rate(s):
    return float(s.strip())

def parse_date(s):
    return date.fromisoformat(s.strip())

lines = load_csv('input/commission_lines.csv')
customers = {norm(r['customer_id']): r for r in load_csv('input/customer_master.csv')}
ledger = load_csv('input/netsuite_revenue_june.csv')
exceptions = load_csv('input/commission_exceptions.csv')
cosells = load_csv('input/co_sell_register.csv')

# June ledger by normalized deal ref
june_by_deal = defaultdict(list)
for r in ledger:
    pd = parse_date(r['posting_date'])
    if pd.year == 2026 and pd.month == 6:
        june_by_deal[norm(r['deal_ref'])].append(r)

net_by_deal = {d: sum(parse_amount(r['amount_usd']) for r in rs) for d, rs in june_by_deal.items()}
ledger_cust_by_deal = {}
for d, rs in june_by_deal.items():
    custs = {norm(r['customer_id']) for r in rs}
    if len(custs) == 1:
        ledger_cust_by_deal[d] = next(iter(custs))
    else:
        ledger_cust_by_deal[d] = None
        print('WARNING mixed customers for', d, custs)

# Active exception by deal
exc_by_deal = {}
for r in exceptions:
    d = norm(r['deal_id'])
    status = r['status'].strip().lower()
    eff_from = parse_date(r['effective_from'])
    eff_to = parse_date(r['effective_to'])
    if status == 'active' and eff_from <= RUN_DATE <= eff_to:
        # take an active one; if multiple active, note
        if d in exc_by_deal:
            print('WARNING multiple active exceptions for', d, r, exc_by_deal[d])
        exc_by_deal[d] = r

# Co-sell validation
cosell_by_deal = defaultdict(list)
for r in cosells:
    cosell_by_deal[norm(r['deal_id'])].append(r)

lines_by_deal = defaultdict(list)
for r in lines:
    lines_by_deal[norm(r['deal_id'])].append(r)

valid_cosell = set()
for d, regs in cosell_by_deal.items():
    if not all(norm(x['status'])=='active' for x in regs):
        continue
    reg_partners = sorted(norm(x['partner']) for x in regs)
    line_partners = sorted(norm(x['source_report']) for x in lines_by_deal.get(d, []))
    if reg_partners != line_partners or len(line_partners) != len(set(line_partners)):
        continue
    if abs(sum(parse_rate(x['share_pct']) for x in regs) - 100.0) > 1e-9:
        continue
    valid_cosell.add(d)

# share by partner for valid cosells
share_by_deal_partner = {}
for d in valid_cosell:
    for x in cosell_by_deal[d]:
        share_by_deal_partner[(d, norm(x['partner']))] = parse_rate(x['share_pct'])/100.0

def end_user_type(cust_id):
    c = customers[norm(cust_id)]
    if norm(c['account_class']) == 'house':
        return 'house'
    fid = parse_date(c['first_invoice_date'])
    return 'new' if fid >= date(2025,7,1) else 'renewal'

def standard_rate(t):
    return {'new':8.0, 'renewal':4.0, 'house':0.0}[t]

findings = []
detail = []
for r in lines:
    lid = r['line_id']
    src = r['source_report']
    did = r['deal_id']
    d = norm(did)
    reported_rate = parse_rate(r['reported_rate_pct'])
    revenue = parse_amount(r['revenue_usd'])

    # customer from ledger June postings, else partner
    if d in june_by_deal and ledger_cust_by_deal.get(d):
        cust_id = ledger_cust_by_deal[d]
    else:
        cust_id = r['customer_id']
    ut = end_user_type(cust_id)
    policy_rate = standard_rate(ut)
    if d in exc_by_deal:
        policy_rate = parse_rate(exc_by_deal[d]['approved_rate_pct'])

    # duplicate?
    is_dup = False
    if len(lines_by_deal[d]) > 1 and d not in valid_cosell:
        is_dup = True

    # ledger match?
    commissionable = policy_rate > 0
    matched = True
    net = net_by_deal.get(d, 0.0)
    if d in valid_cosell:
        target = net * share_by_deal_partner[(d, norm(src))]
    else:
        target = net
    if commissionable:
        matched = abs(revenue - target) <= 0.01 * revenue
    else:
        matched = True  # no match needed

    rate_mismatch = reported_rate != policy_rate

    if is_dup:
        code = 'DUPLICATE_LINE'
    elif commissionable and not matched:
        code = 'UNMATCHED_TO_LEDGER'
    elif rate_mismatch:
        code = 'RATE_MISMATCH'
    else:
        code = None

    detail.append((lid, did, src, cust_id, ut, policy_rate, reported_rate, revenue, net, target, commissionable, matched, code, d in exc_by_deal, d in valid_cosell))
    if code:
        findings.append((lid, did, src, code))

print('line_id,deal_id,source,cust,type,policy_rate,reported_rate,revenue,net,target,commissionable,matched,code,exception,cosell')
for x in detail:
    print(','.join(str(y) for y in x))

print('\nFindings:')
for f in findings:
    print(f)
from collections import Counter
c = Counter(f[3] for f in findings)
print('\nCounts:', c, 'total', len(lines), 'flagged', len(findings), 'compliant', len(lines)-len(findings))
print('valid_cosell', valid_cosell)
print('active_exceptions', {k:v['exception_code'] for k,v in exc_by_deal.items()})
